    $unset: [
      'created_on',
      'temperature_outcome',
      'temperature_rule',
      'dash_firstVisitAppointments',
      'lead_temperature',
      'temperature_calculated_at',
    ],
  },
  {
    $merge: {
      into: 'new-telecrm',
      on: '_id',
      whenMatched: 'replace',
      whenNotMatched: 'discard',
    },
  },
];

return [{ json: { ...item, phone, cleanupPipeline: JSON.stringify(pipeline) } }];
